# verify all candidate translations of demo 2 template at seed location
seed=np.argwhere(in2==9); r0,c0=seed.min(0); mask=seed-np.array([r0,c0]);
placements=[]
for r in range(in2.shape[0]-mask[:,0].max()):
 for c in range(in2.shape[1]-mask[:,1].max()):
  coords=mask+np.array([r,c])
  if np.all(in2[coords[:,0],coords[:,1]]==0): placements.append((r,c))
union=set()
for r,c in placements:
 union.update(map(tuple,mask+np.array([r,c])))
diffs=set(map(tuple,np.argwhere(out2!=in2)))
print('mask',mask.tolist(),'placements',placements,'union==diffs',union==diffs,'extras',diffs-union,'omitted',union-diffs)

seed=np.argwhere(test==5); r0,c0=seed.min(0); mask=seed-np.array([r0,c0]); placements=[]
for r in range(test.shape[0]-int(mask[:,0].max())):
 for c in range(test.shape[1]-int(mask[:,1].max())):
  coords=mask+np.array([r,c])
  if np.all(test[coords[:,0],coords[:,1]]==0): placements.append((r,c))
out=test.copy()
for r,c in placements:
 coords=mask+np.array([r,c]); out[coords[:,0],coords[:,1]]=5
print(mask.tolist(),placements, np.sum(out!=test), '\n'+'\n'.join(' '.join(map(str,row)) for row in out))
